        metaTitle: "Diploma Notarial Translation in Israel — Price, Process & Timeline | BEITON",
        metaDescription: "Notarial translation of a diploma or academic certificate in Israel: what the law requires, the regulated fee, and the documents usually needed.",
        intro: "A notarial translation of a diploma or academic certificate may be needed for studies abroad, for a professional license in another country, or for skilled-worker immigration. Universities, regulatory bodies, employers and immigration authorities may ask that the translation be certified by a notary. Whether a notarial translation is needed, and whether an apostille is needed on it, is decided by the receiving institution or country.",
        whatIsTitle: "What is a notarial translation of a diploma?",
        whatIsBody: "A notarial translation of a diploma is a translation of an academic document, such as a bachelor's degree, master's degree, doctorate, transcript or other educational certificate, accompanied by the certification of a licensed notary under the Notaries Law, 1976 (חוק הנוטריונים, תשל״ו-1976), that the translation is correct. Under section 15 of the Notaries Law, a notary may certify a translation only if the notary masters both the language of the original and the language of the translation, and only if the notary made the translation or checked that it is correct. Where a translation is needed between other languages, the usual route is a translator's declaration: an affidavit in which the translator declares, before a notary, that the translation is correct.",
