        intro: "قد تُطلب الترجمة التوثيقية للشهادة الجامعية (الدبلوم) لمتابعة الدراسة في الخارج، أو للحصول على ترخيص مهني في دولة أجنبية، أو لتقديم طلب هجرة للعمالة المتخصصة. قد تشترط الجامعات والهيئات التنظيمية وأرباب العمل الدوليون وسلطات الهجرة تصديق كاتب عدل على صحة الترجمة، والجهة المستقبلة هي التي تحدد ذلك.",
