        intro: "A notarial translation of a driver's license may be requested from Israelis staying abroad for a long period, from new immigrants converting a foreign license to an Israeli one, and from foreign residents in Israel converting their license. Transportation authorities, car rental companies and insurers in some countries ask for a certified translation of the license. Whether a notarial translation is needed, and in what form, is decided by the receiving authority.",
