        metaTitle: "Marriage Certificate Notarial Translation in Israel — Price & Process | BEITON",
        metaDescription: "Notarial translation of a marriage certificate in Israel: what the law requires, the regulated fee, and the documents usually needed.",
        intro: "A notarial translation of a marriage certificate may be needed for immigration and foreign citizenship applications, for registering a marriage abroad, and for procedures such as a name change or family reunification. Embassies, immigration authorities, courts and financial institutions abroad may ask that the certificate be translated and the translation certified by a notary. Whether that is needed, and whether an apostille is needed on it, is decided by the receiving authority or country.",
        whatIsTitle: "What is a notarial translation of a marriage certificate?",
        whatIsBody: "A notarial translation of a marriage certificate is a translation accompanied by the certification of a licensed notary under the Notaries Law, 1976 (חוק הנוטריונים, תשל״ו-1976), that the translation is correct. Under section 15 of the Notaries Law, a notary may certify a translation only if the notary masters both the language of the original and the language of the translation, and only if the notary made the translation or checked that it is correct. Where a translation is needed between other languages, the usual route is a translator's declaration: an affidavit in which the translator declares, before a notary, that the translation is correct.",
