        metaTitle: "Notarial Signature Authentication on Contracts — Price & Process | BEITON",
        metaDescription: "Notarial signature authentication on contracts in Israel: 197 ₪ for the first signer, signer present in person. What the law requires when a contract is signed before a notary.",
        intro: "Notarial signature authentication on a contract is a procedure in which a licensed notary certifies that the signatory signed the document in their presence, of their own free will, and after proper identification. It may be requested for transactions such as property sales, partnership agreements and investment contracts. Under section 19 of the Notaries Law, 1976, the notary's certification is sufficient evidence in legal proceedings, without further proof, of what the notary states in it.",
