        intro: "Нотариальное заверение подписи на договоре: нотариальное действие, при котором нотариус удостоверяет подпись человека, который предстал перед ним, был идентифицирован и подписал документ в его присутствии (статья 11 Закона о нотариусах). Такое заверение может потребовать другая сторона или принимающий орган, например при продаже недвижимости, в партнёрских соглашениях и инвестиционных контрактах. По статье 19 закона нотариальное удостоверение является достаточным доказательством в судебном процессе того, что было сказано и сделано перед нотариусом, как указано в удостоверении.",
