        intro: "A continuing power of attorney is a legal document that allows a person to appoint an attorney-in-fact to act on their behalf in the future, if they become unable to make decisions, for example due to dementia, serious illness or an accident. It is intended to take effect when the principal loses capacity. It is signed before a lawyer who completed the required training, and it is not a notarial act.",
